import sys

def count_permutations(n, k, p):
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = 1

    for i in range(2, n + 1):
        for j in range(2, min(i, k) + 1):
            dp[i][j] = (dp[i-1][j-1] + (i - j + 1) * dp[i-1][j]) % p

    return sum(dp[n]) % p

if __name__ == "__main__":
    n, k, p = map(int, sys.stdin.readline().split())
    result = count_permutations(n, k, p)
    print(result)

def count_permutations_with_runs(n, k, p):
    from functools import lru_cache

    @lru_cache(None)
    def dp(pos, max_so_far, run_length):
        if pos == n:
            return 1

        count = 0
        for next_num in range(1, n + 1):
            if not used[next_num]:
                if next_num > max_so_far:
                    # Continuing an increasing run
                    count += dp(pos + 1, next_num, run_length + 1)
                elif run_length < k:
                    # Starting a new run, only if the current run length is less than k
                    count += dp(pos + 1, next_num, 1)

                count %= p

        return count

    used = [False] * (n + 1)
    return dp(0, 0, 0)

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().strip()
    n, k, p = map(int, data.split())
    result = count_permutations_with_runs(n, k, p)
    print(result)
